CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', age INTEGER NOT NULL, salt TEXT NOT NULL, pass TEXT NOT NULL, avatar TEXT, cover TEXT, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audios(id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, descr TEXT NOT NULL DEFAULT '', secs INTEGER NOT NULL, popup INTEGER NOT NULL DEFAULT 1, vis TEXT NOT NULL DEFAULT 'all', key TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS likes(user_id INTEGER NOT NULL, audio_id INTEGER NOT NULL, PRIMARY KEY(user_id, audio_id));
CREATE TABLE IF NOT EXISTS follows(follower INTEGER NOT NULL, followee INTEGER NOT NULL, PRIMARY KEY(follower, followee));
CREATE TABLE IF NOT EXISTS notifs(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, type TEXT NOT NULL, actor_id INTEGER NOT NULL, audio_id INTEGER, created INTEGER NOT NULL, seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v INTEGER NOT NULL);
INSERT OR IGNORE INTO meta VALUES('taps', 0);
CREATE INDEX IF NOT EXISTS i_aud_owner ON audios(owner_id);
CREATE INDEX IF NOT EXISTS i_notif_user ON notifs(user_id, id);
CREATE INDEX IF NOT EXISTS i_fol_ee ON follows(followee);
